fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 0.5) {
        val rounded = seconds.roundToInt()
        if (Math.abs(seconds - rounded) < 0.05) "${rounded}s" else String.format("%.1fs", seconds)
    } else {
        val denominator = (1_000_000_000.0 / exposureTimeNs).roundToInt().coerceAtLeast(1)
        "1/${denominator}s"
    }
}

